            "policyLimit": {"amount": 5000, "currency": "CHF"}
        },
        headers=auth_headers,
        timeout=10
    )
    assert patch_resp.status_code == 404, f"Expected 404, got {patch_resp.status_code}: {patch_resp.text}"
